// Reproducible browser wrapper for the pinned, dependency-free xterm parser.
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const pkg = path.join(root, 'node_modules/@xterm/headless');
const dest = path.join(root, 'web/public/m/vendor');
fs.mkdirSync(dest, { recursive: true });
const source = fs.readFileSync(path.join(pkg, 'lib-headless/xterm-headless.js'), 'utf8')
    .replace(/\/\/# sourceMappingURL=.*$/m, '');
fs.writeFileSync(path.join(dest, 'xterm-headless.mjs'),
    '// @xterm/headless 5.5.0 — MIT; see xterm-LICENSE. Generated by scripts/vendor-mobile-terminal.js.\n' +
    'const exports = {};\n' + source + '\nexport const Terminal = exports.Terminal;\n');
// npm's headless package omits LICENSE. The upstream 5.5.0 license is
// checked in beside the bundle as xterm-LICENSE.
